            const foulBarMax = 5;
            const foulPeriodLabel = currentQuarter <= 4 ? getPeriodLabel(currentQuarter) : `${getPeriodLabel(4)}+`;
            const timeoutScopeLabel = currentQuarter > 4 ? getPeriodLabel(currentQuarter) : 'Reg';
